declarations.code:
friend constexpr /* iterator */

operator+(const /* iterator */ &i, difference_type n)

    requires ranges::random_access_range</* Base */>;

friend constexpr /* iterator */

operator+(difference_type n, const /* iterator */ &i)

    requires ranges::random_access_range</* Base */>;

friend constexpr /* iterator */

operator-(const /* iterator */ &i, difference_type n)

    requires ranges::random_access_range</* Base */>;

intro:
Performs iterator arithmetic or calculates the distance.

pos_ is the underlying index, and Base is the (possibly const-qualified) type of underlying view.

Equivalent to:

1) auto temp = i; temp += n; return temp;

2) return i + n;

3) auto temp = i; temp -= n; return temp;

4) return i.pos_ - j.pos_;

These functions are not visible to ordinary unqualified or qualified lookup, and can only be found by argument-dependent lookup when enumerate_view::iterator<Const> is an associated class of the arguments.

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view = std::ranges::enumerate_view{values};
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);
    (void)view.base();
    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
